numbercontrol.script:
function onDragStart(button, x, y, draginfo)
	draginfo.setType("tcwiz_swap");
	draginfo.setStringData(getName():gsub("^score_", ""));
	draginfo.setDescription(tostring(getValue()));
	return true;
end
function onDrop(x, y, draginfo)
	if draginfo.isType("tcwiz_swap") then
		TCWizard.swapScores(draginfo.getStringData(), getName():gsub("^score_", ""));
		return true;
	end
end

windowclass.script:
function onInit()
	update();
end
function setText(s)
	text.setValue(s);
end
function update()
	local bShow = TCWizard.getInstructionsShown();
	text.setVisible(bShow);
	button_toggle.setValue(bShow and 0 or 1);
end
function toggleInstructions()
	TCWizard.setInstructionsShown(not TCWizard.getInstructionsShown());
end

local _n = 0;
function setData(n, o)
	_n = n;
	button.setText(o.label or "");
	if o.tip then button.setTooltipText(o.tip); end
	if o.disabled then
		button.setEnabled(false);
	end
	detail.setValue(o.detail or "");
	detail.setVisible((o.detail or "") ~= "");
end
function onPress()
	TCWizard.chooseOption(_n);
end

function onInit()
	update();
end
function update()
	local t = TCWizard.getTask();
	local S = TCWizard.getState();
	options.closeAll();
	grid.closeAll();
	if S.waiting or (not t and (S.rollsPending or 0) > 0) then
		title.setValue("Rolling...");
		text.setValue(S.waiting and "Waiting for the dice. If the roll never reaches chat, press Roll again." or "Waiting for the dice.");
		retry.setVisible(S.waiting ~= nil);
		return;
	end
	retry.setVisible(false);
	if not t then
		title.setValue(S.done and "Your careers are over" or "");
		text.setValue(S.done and "Your Traveller has mustered out. Check the Benefits and Skills pages, then Finish." or "");
		return;
	end
	title.setValue(t.title or "");
	text.setValue(t.text or "");
	local list = t.grid and grid or options;
	for i, o in ipairs(t.options or {}) do
		local w = list.createWindow();
		w.setData(i, o);
	end
end

local _sPath = "";
function setData(node)
	_sPath = DB.getPath(node);
	name.setValue(DB.getValue(node, "name", ""));
	local sMods = DB.getValue(node, "characteristics", "");
	mods.setValue(sMods ~= "" and sMods or "no characteristic changes");
	source.setValue(TCWizard.getSourceName(node));
end
function onAdd()
	TCWizard.selectSpecies(DB.findNode(_sPath));
end
function onOpen()
	TCWizard.openRecord("reference_race", _sPath);
end

local _sKind, _vKey = "", nil;
local _bSetting = false;
function setData(sKind, vKey, sLabel, bOn, bLocked)
	_sKind, _vKey = sKind, vKey;
	label.setValue(sLabel);
	_bSetting = true;
	check.setValue(bOn and 1 or 0);
	_bSetting = false;
	check.setReadOnly(bLocked and true or false);
end
function onToggle(bOn)
	if _bSetting then return; end
	if _sKind == "background" then
		TCWizard.toggleBackground(_vKey, bOn);
	elseif _sKind == "package" then
		TCWizard.togglePackageSkill(_vKey, bOn);
	end
end

local _n = 0;
local _bSetting = false;
function setData(n, b)
	_n = n;
	local d = b.def;
	name.setValue(string.format("%s (up to Cr%d, TL%d) - from %s", b.name, d.limit, d.tl, b.from or ""));
	_bSetting = true;
	item.clear();
	item.add("", "(choose)");
	for _, node in ipairs(TCWizard.getBenefitItems(b)) do
		item.add(DB.getPath(node), DB.getValue(node, "name", "") .. "  " .. DB.getValue(node, "cost", ""));
	end
	item.setValue(b.item or "");
	_bSetting = false;
end
function onPick(sPath)
	if _bSetting then return; end
	TCWizard.chooseBenefitItem(_n, sPath ~= "" and sPath or nil);
end

local _n = 0;
function getIndex() return _n; end
function setData(n, inj)
	_n = n;
	local s = string.format("%s -%d", inj.stat:upper(), inj.points);
	if inj.cover then s = s .. string.format(": employer pays %d%%, you pay Cr%d", inj.cover, inj.cost or 0); end
	if inj.settled then s = s .. (inj.restored and " - restored" or " - kept"); end
	text.setValue(s);
	roll.setVisible(not inj.cover and not inj.settled);
	restore.setVisible(inj.cover ~= nil and not inj.settled);
	keep.setVisible(not inj.settled);
end
